	xordm8	(10416), c	; F5536C  xor (0x28b0),C
	ldb_d8	c, (10416)	; F55370  ld C,(0x28b0)
	and	c, 16	; F55374  and C,0x10
	jr	z, 4	; F55377  jr Z,0xf5537d
