	sla	xhl, 8	; F63BB2  sla 0x08,XHL
	addda32	xhl, (13828)	; F63BB5  add XHL,(0x3604)
	stda32	(4718), xhl	; F63BB9  ld (0x126e),XHL
	xor	xhl, xhl	; F63BBD  xor XHL,XHL
	ret	; F63BBF  ret

